    /// <summary>
    /// Python's argument binding against .NET methods and constructors found by reflection: positional arguments first,
    /// then keyword arguments by parameter name, defaults for the rest; among the overloads that take the arguments, the
    /// one whose parameter types they have (Typhon's typed versions of a function) over a late-bound one.
    /// </summary>
    internal static class PyArgs
    {
        public static T? Best<T>(IEnumerable<T> candidates, object?[] args, IDictionary<string, object?>? kw,
            out object?[] call, IDictionary<string, object?>? defaults = null) where T : System.Reflection.MethodBase
        {
            T? best = null;
            int bestScore = -1, mostExactMatches = 0;
            call = Array.Empty<object?>();
            foreach (var m in candidates)
            {
                int score = Bind(m.GetParameters(), args, kw, out var c, out int exactMatches, defaults);
                if (score >= 0 && (score > bestScore || score == bestScore && exactMatches > mostExactMatches))
                {
                    best = m;
                    bestScore = score;
                    mostExactMatches = exactMatches;
                    call = c;
                }
            }
            return best;
        }

        /// <summary>Python's TypeError for arguments no overload takes: an unknown keyword, or ones missing or too many.</summary>
        public static Exception NoFit(string name, IDictionary<string, object?>? kw, IEnumerable<System.Reflection.MethodBase> candidates)
        {
            var names = new HashSet<string>(candidates.SelectMany(m => m.GetParameters()).Select(p => p.Name ?? ""));
            string? unknown = kw?.Keys.FirstOrDefault(k => !names.Contains(k));
            return new InvalidCastException(unknown != null ? $"{name}() got an unexpected keyword argument '{unknown}'"
                                                            : $"{name}() got missing, repeated or too many arguments");
        }

        internal static bool IsPositionalRest(System.Reflection.ParameterInfo parameter) =>
            parameter.IsDefined(typeof(ParamArrayAttribute), false) || parameter.IsDefined(typeof(PyPackedArgumentsAttribute), false);

        internal static bool IsPositionalOnly(System.Reflection.ParameterInfo parameter) =>
            parameter.IsDefined(typeof(PyPositionalOnlyAttribute), false);

        internal static bool IsKeywordOnly(System.Reflection.ParameterInfo parameter) =>
            parameter.IsDefined(typeof(PyKeywordOnlyAttribute), false);

        internal static int PositionalLimit(System.Reflection.ParameterInfo[] parameters, int fixedCount)
        {
            int firstKeyword = Array.FindIndex(parameters, IsKeywordOnly);
            return firstKeyword < 0 ? fixedCount : Math.Min(fixedCount, firstKeyword);
        }

        /// <summary>The arguments of a call to a method with these parameters, and how well they fit (-1: they do not).</summary>
        public static int Bind(System.Reflection.ParameterInfo[] ps, object?[] args, IDictionary<string, object?>? kw,
            out object?[] call, IDictionary<string, object?>? defaults = null) => Bind(ps, args, kw, out call, out _, defaults);

        static int Bind(System.Reflection.ParameterInfo[] ps, object?[] args, IDictionary<string, object?>? kw,
            out object?[] call, out int exactMatches, IDictionary<string, object?>? defaults)
        {
            exactMatches = 0;
            call = new object?[ps.Length];
            if (ps.Any(p => p.ParameterType.IsByRef || p.ParameterType == typeof(NoInit))) return -1;
            bool hasKeywords = ps.Length > 0 && ps[^1].IsDefined(typeof(PyKeywordArgumentsAttribute), false);
            int parameterCount = hasKeywords ? ps.Length - 1 : ps.Length;
            int restIndex = Array.FindIndex(ps, IsPositionalRest);
            int positionalLimit = PositionalLimit(ps, restIndex < 0 ? parameterCount : restIndex);
            if (restIndex < 0 && args.Length > positionalLimit) return -1;
            int score = 0, byName = 0;
            for (int i = 0; i < parameterCount; i++)
            {
                if (i == restIndex) continue;
                var p = ps[i];
                object? v;
                if (i < positionalLimit && i < args.Length)
                {
                    if (kw != null && p.Name != null && !IsPositionalOnly(p) && kw.ContainsKey(p.Name)) return -1; // given twice
                    v = args[i];
                }
                else if (kw != null && p.Name != null && !IsPositionalOnly(p) && kw.TryGetValue(p.Name, out v)) byName++;
                else if (p.Name == null || defaults == null || !defaults.TryGetValue(p.Name, out v))
                {
                    if (!p.IsOptional) return -1;
                    call[i] = p.HasDefaultValue ? p.DefaultValue : Type.Missing;
                    continue;
                }
                int fit = Fit(v, p.ParameterType, out call[i]);
                if (fit < 0) return -1;
                score += fit;
                if (fit == 2 && v!.GetType() == p.ParameterType) exactMatches++;
            }
            if (kw != null && byName != kw.Count && !hasKeywords) return -1; // a name no parameter has
            if (hasKeywords)
            {
                var extra = new OrderedDictionary<string, object?>();
                if (kw != null && byName != kw.Count)
                    foreach (var pair in kw)
                        if (!ps.Take(parameterCount).Any(parameter => parameter.Position != restIndex &&
                            !IsPositionalOnly(parameter) && parameter.Name == pair.Key))
                            extra[pair.Key] = pair.Value;
                call[^1] = extra;
            }
            if (restIndex >= 0)
            {
                var elem = ps[restIndex].ParameterType.GetElementType()!;
                var rest = Array.CreateInstance(elem, Math.Max(0, args.Length - positionalLimit));
                for (int i = positionalLimit; i < args.Length; i++)
                {
                    int fit = Fit(args[i], elem, out var converted);
                    if (fit < 0) return -1;
                    if (fit == 2 && args[i]!.GetType() == elem) exactMatches++;
                    rest.SetValue(converted, i - positionalLimit);
                }
                call[restIndex] = rest;
            }
            return score;
        }

        static int Fit(object? v, Type t, out object? converted)
        {
            converted = v;
            if (v == null) return !t.IsValueType || Nullable.GetUnderlyingType(t) != null ? 1 : -1;
            if (t == typeof(object)) return 0;
            if (t.IsInstanceOfType(v)) return 2;
            if (t == typeof(string) && v is PyString text)
            {
                converted = text.Text;
                return 1;
            }
            var u = Nullable.GetUnderlyingType(t) ?? t;
            // an int where a float is expected, as Python allows
            if (u == typeof(double) && (v is long || v is int || v is bool))
            {
                converted = Convert.ToDouble(v, CultureInfo.InvariantCulture);
                return 1;
            }
            object? primitive = Builtins.IntegerValue(v);
            if (primitive is BigInteger integer && TryIntegralArgument(integer, u, out converted)) return 1;
            if (!ReferenceEquals(primitive, v) && primitive is long small && TryIntegralArgument(small, u, out converted)) return 1;
            return -1;
        }

        internal static object? ConvertArgument(object? value, Type target)
        {
            if (value == null || target.IsInstanceOfType(value)) return value;
            if (target == typeof(string) && value is PyString text) return text.Text;
            var underlying = Nullable.GetUnderlyingType(target) ?? target;
            object? primitive = Builtins.IntegerValue(value);
            if (primitive is BigInteger integer && TryIntegralArgument(integer, underlying, out var converted))
                return converted;
            if (!ReferenceEquals(primitive, value) && primitive is long small && TryIntegralArgument(small, underlying, out converted))
                return converted;
            if (value is ITuple tuple && IsValueTupleType(underlying))
            {
                int index = 0;
                object result = ConvertValueTuple(tuple, underlying, ref index);
                if (index != tuple.Length) throw new InvalidCastException("tuple has the wrong number of items");
                return result;
            }
            return Convert.ChangeType(value, underlying, CultureInfo.InvariantCulture);
        }

        internal static bool IsValueTupleType(Type type) => type == typeof(ValueTuple) ||
            type.IsGenericType && type.Namespace == "System" && type.Name.StartsWith("ValueTuple`", StringComparison.Ordinal);

        static object ConvertValueTuple(ITuple value, Type type, ref int offset)
        {
            if (type == typeof(ValueTuple)) return default(ValueTuple);
            var elementTypes = type.GetGenericArguments();
            var arguments = new object?[elementTypes.Length];
            int direct = Math.Min(7, elementTypes.Length);
            if (offset + direct > value.Length) throw new InvalidCastException("tuple has the wrong number of items");
            for (int part = 0; part < direct; part++)
                arguments[part] = ConvertArgument(value[offset++], elementTypes[part]);
            if (elementTypes.Length == 8)
                arguments[7] = ConvertValueTuple(value, elementTypes[7], ref offset);
            return Activator.CreateInstance(type, arguments)!;
        }

        static bool TryIntegralArgument(BigInteger value, Type target, out object? converted)
        {
            try
            {
                converted = target.IsEnum ? null : Type.GetTypeCode(target) switch
                {
                    TypeCode.SByte => (sbyte)value,
                    TypeCode.Byte => (byte)value,
                    TypeCode.Int16 => (short)value,
                    TypeCode.UInt16 => (ushort)value,
                    TypeCode.Int32 => (int)value,
                    TypeCode.UInt32 => (uint)value,
                    TypeCode.Int64 => (long)value,
                    TypeCode.UInt64 => (ulong)value,
                    _ => null,
                };
            }
            catch (OverflowException)
            {
                converted = null;
            }
            return converted != null;
        }
    }

    internal static partial class Builtins
    {
        static System.Reflection.ConstructorInfo[] CallableConstructors(Type type) =>
            type.IsDefined(typeof(PySourceAttribute), false)
                ? type.GetConstructors(System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic)
                : type.GetConstructors();

        /// <summary>
        /// cls(args) for a class known at run time: the constructor that takes this many arguments (optional ones
        /// get their defaults), preferring one whose parameter types the arguments have over a late-bound one.
        /// </summary>
        static bool TryCustomAllocation(Type type, object?[] args, IDictionary<string, object?>? keywords, out object? result)
        {
            result = null;
            if (!type.IsDefined(typeof(PyCustomAllocationAttribute), inherit: false)) return false;
            const System.Reflection.BindingFlags declaredStatic = System.Reflection.BindingFlags.DeclaredOnly |
                System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic;
            var order = PyMetaclasses.HasRuntimeSubclassStorage(type) ? PyMetaclasses.MethodOrder(type) : PyClassDescriptors.ClrBases(type);
            foreach (Type owner in order)
            {
                object? allocator;
                if (TryGetClassData(owner, "__new__", out var member, before: owner.BaseType))
                    allocator = PyMetaclasses.Bind(member, null, type);
                else if (owner.GetMethods(declaredStatic).Any(method => method.Name == "__new__"))
                    allocator = new PyBoundMethod(owner, "__new__", includeNonPublic: true);
                else continue;

                result = __invoke_kw(allocator, [type, .. args], keywords);
                if (result != null && type.IsInstanceOfType(result)) InitializeAllocated(result, args, keywords);
                return true;
            }
            return false;
        }

