            if (t == typeof(frozendict<object, object>)) return ConstructFrozenDict(args, null);
            if (t == typeof(OrderedDictionary<object, object>)) return dict(ConstructFrozenDict(args, null, "dict"));
            if (t == typeof(List<object>) || t == typeof(HashSet<object>) || t == typeof(frozenset<object>) || t == typeof(ITuple))
            {
                if (args.Length > 1) throw new InvalidCastException($"{PyTypeName(t)} expected at most 1 argument, got {args.Length}");
                var items = args.Length == 0 ? Array.Empty<object?>() : __iter_dyn(args[0]!);
                if (t == typeof(List<object>)) return items.ToList();
                if (t == typeof(ITuple)) return new PyTuple<object?>(items);
                if (t == typeof(frozenset<object>)) return frozenset(items);
                var set = __newset<object?>();
                set.UnionWith(items);
                return set;
            }
            return ConstructClr(t, args);
        }

        internal static object? ConstructClr(Type t, object?[] args)
        {
            System.Reflection.ConstructorInfo? best = null; int bestScore = -1;
            object?[]? boundRest = null;
            foreach (var c in CallableConstructors(t))
            {
                var ps = c.GetParameters();
                if (ps.Any(PyArgs.IsPositionalRest))
                {
                    int restScore = PyArgs.Bind(ps, args, null, out var rest);
                    if (restScore > bestScore)
                    {
                        best = c;
                        bestScore = restScore;
                        boundRest = rest;
                    }
                    continue;
                }
                if (args.Length > ps.Length || ps.Take(args.Length).Any(p => p.ParameterType.IsByRef)) continue;
                if (ps.Skip(args.Length).Any(p => !p.IsOptional)) continue;
                int score = 0; bool ok = true;
                for (int i = 0; i < args.Length && ok; i++)
                {
                    var pt = ps[i].ParameterType;
                    if (args[i] == null) { ok = !pt.IsValueType || Nullable.GetUnderlyingType(pt) != null; continue; }
                    if (pt == typeof(object)) continue;
                    if (pt.IsInstanceOfType(args[i])) { score += 2; continue; }
                    if (args[i] is IConvertible && (pt.IsPrimitive || Nullable.GetUnderlyingType(pt)?.IsPrimitive == true)) { score += 1; continue; }
                    ok = false;
                }
                if (ok && score > bestScore) { best = c; bestScore = score; boundRest = null; }
            }
            if (best == null) throw new InvalidCastException($"{t.Name}() takes no constructor for {args.Length} arguments");
            if (boundRest != null) return Unwrapped(() => best.Invoke(boundRest));
            var bps = best.GetParameters();
            var call = new object?[bps.Length];
            for (int i = 0; i < bps.Length; i++)
            {
                if (i >= args.Length) { call[i] = bps[i].HasDefaultValue ? bps[i].DefaultValue : Type.Missing; continue; }
                var pt = bps[i].ParameterType;
                call[i] = args[i] == null || pt.IsInstanceOfType(args[i]) || pt == typeof(object) ? args[i]
                    : Convert.ChangeType(args[i], Nullable.GetUnderlyingType(pt) ?? pt, CultureInfo.InvariantCulture);
            }
            return Unwrapped(() => best.Invoke(call));
        }

        /// <summary>
        /// f(*args) on a late-bound callable: a Typhon function value, a bound method, a .NET delegate, or an object with
        /// __call__ (the arguments are known only as a sequence, so the call is made at run time).
        /// </summary>
        /// <summary>super().m(...) where no further class defines m: Python's AttributeError.</summary>
        public static dynamic __no_super(string name) => throw new MissingMemberException($"'super' object has no attribute '{name}'");

        /// <summary>x.__name__ of a class, function or other object known only at run time.</summary>
        public static string __name_of(object? o) => o switch
        {
            Type t => PyTypeName(t),
            PyFunction f => f.__name__,
            PyBoundMethod m => m.__name__,
            Delegate d => d.Method.Name,
            null => throw new MissingMemberException("'NoneType' object has no attribute '__name__'"),
            _ => (string)((dynamic)o).__name__,
        };

        /// <summary>X.__module__: the module a class (or a function) is defined in; 'builtins' for the runtime's and .NET's types.</summary>
        public static string __module_of(object? o) => o switch
        {
            PyFunction f => f.__module__,
            Type t => ModuleOfType(t),
            null => throw new MissingMemberException("'NoneType' object has no attribute '__module__'"),
            _ => (string)((dynamic)o).__module__,
        };

        static readonly ConditionalWeakTable<Type, string> ClassModuleNames = new();

        public static void __remember_class_module(Type type, object? name)
        {
            if (name is string module) ClassModuleNames.AddOrUpdate(type, module);
        }

        /// <summary>The module of a class: a Typhon class's is the module class it is nested in; the runtime's and .NET's are builtins.</summary>
        static string ModuleOfType(Type t)
        {
            if (t == typeof(Typhon.Stdlib.types.UnionType)) return "typing";
            if (t.DeclaringType == typeof(Typhon.Stdlib._typing) && t != typeof(Typhon.Stdlib._typing.NoDefaultType)) return "typing";
            if (t == typeof(PyPartial)) return "functools";
            if (t.DeclaringType == typeof(Typhon.Stdlib.collections.abc)) return "collections.abc";
            if (t.DeclaringType == typeof(Typhon.Stdlib.@operator)) return "operator";
            if (t is PyLocalDataClass local) return local.PythonModule;
            if (t is PyPlainEnumType enumeration) return enumeration.PythonModule;
            if (t is PyIntEnumType integerEnumeration) return integerEnumeration.Module;
            var definitionType = t.IsGenericType ? t.GetGenericTypeDefinition() : t;
            if (ClassModuleNames.TryGetValue(definitionType, out var capturedName)) return capturedName;
            var outer = t;
            while (outer.DeclaringType != null) outer = outer.DeclaringType;
            if (outer.GetCustomAttributes(typeof(PySourceAttribute), inherit: false).FirstOrDefault() is PySourceAttribute source)
                return source.Module;
            if (t.IsGenericType)
            {
                var definition = t.GetGenericTypeDefinition();
                if (definition == typeof(PyArray<>)) return "array";
                if (Typhon.Stdlib.collections.CanonicalClass(t) != null) return "collections";
            }
            if (t.Namespace is string ns && (ns == "System" || ns.StartsWith("System.") || ns.StartsWith("Microsoft.") || ns.StartsWith("Typhon."))) return "builtins";
            return outer != t ? outer.Name : t.Namespace ?? "builtins";
        }

        internal static string PythonQualifiedTypeName(Type type)
        {
            string module = ModuleOfType(type), name = PyExc.TypeName(type);
            for (var owner = type.DeclaringType; owner?.DeclaringType != null && module != "builtins"; owner = owner.DeclaringType)
                name = PyTypeName(owner) + "." + name;
            return module == "builtins" ? name : module + "." + name;
        }

        /// <summary>A type's Python name: int for long, str for string, list for List&lt;T&gt;, a Typhon class's own name.</summary>
        public static string PyTypeName(Type t)
        {
            if (t == typeof(object)) return "object";
            if (PyExc.BuiltinTypeName(t) is string exceptionName) return exceptionName;
            if (t == typeof(Typhon.Stdlib.types.UnionType)) return "Union";
            if (t == typeof(Typhon.Stdlib.types.BuiltinFunctionType)) return "builtin_function_or_method";
            if (t == typeof(Typhon.Stdlib.types.WrapperDescriptorType)) return "wrapper_descriptor";
            if (t == typeof(Typhon.Stdlib.types.MethodDescriptorType)) return "method_descriptor";
            if (t == typeof(Typhon.Stdlib.types.EllipsisType)) return "ellipsis";
            if (t == typeof(Typhon.Stdlib.types.GeneratorType)) return "generator";
            if (t == typeof(Typhon.Stdlib.types.CoroutineType)) return "coroutine";
            if (t == typeof(Typhon.Stdlib.types.AsyncGeneratorType)) return "async_generator";
            if (PyDictViews.Name(t) is string view) return view;
            if (t == typeof(Type)) return "type";
            if (t == typeof(PyRange) || t == typeof(PyBigRange)) return "range";
            if (t == typeof(PySlice)) return "slice";
            if (t == typeof(PySingleton)) return "sentinel";
            if (t == typeof(ITuple)) return "tuple";
            if (t == typeof(Typhon.Stdlib.types.FunctionType)) return "function";
            if (t == typeof(Typhon.Stdlib.types.CodeType)) return "code";
            if (t == typeof(Typhon.Stdlib.types.CellType)) return "cell";
            if (t == typeof(PyPartial)) return "partial";
            if (t == typeof(Typhon.Stdlib.types.MethodType)) return "method";
            if (t == typeof(long) || t == typeof(int) || t == typeof(short) || t == typeof(byte) || t == typeof(System.Numerics.BigInteger)) return "int";
            if (t == typeof(double) || t == typeof(float)) return "float";
            if (t == typeof(Complex)) return "complex";
            if (t == typeof(string)) return "str";
            if (t == typeof(bool)) return "bool";
            if (t == typeof(PyBytes)) return "bytes";
            if (t == typeof(PyByteArray)) return "bytearray";
            if (typeof(PyFunction).IsAssignableFrom(t)) return "function";
            if (t == typeof(PyModule) || t == typeof(Typhon.Stdlib.types.ModuleType)) return "module";
            if (t == typeof(Typhon.Stdlib.types.MappingProxyType)) return "mappingproxy";
            if (t == typeof(Typhon.Stdlib.types.TracebackType)) return "traceback";
            if (t.IsArray && t != typeof(byte[])) return "tuple";
            if (t.IsGenericType)
            {
                var g = t.GetGenericTypeDefinition();
                if (g == typeof(PyOrderedDict<,>)) return "OrderedDict";
                if (g == typeof(List<>)) return "list";
                if (g == typeof(PyZip<>)) return "zip";
                if (g == typeof(OrderedDictionary<,>) || g == typeof(Dictionary<,>)) return "dict";
                if (g == typeof(HashSet<>)) return "set";
                if (g == typeof(PyArray<>)) return "array";
                if (g == typeof(PyTuple<>) || t.FullName?.StartsWith("System.ValueTuple") == true) return "tuple";
            }
            if (t.GetCustomAttributes(typeof(PySourceAttribute), false).OfType<PySourceAttribute>().FirstOrDefault()?.PythonName is string name)
                return name;
            int tick = t.Name.IndexOf('`');
            return tick < 0 ? t.Name : t.Name.Substring(0, tick);
        }

        /// <summary>f(*args, **kwargs) / f(x, key=v) on a late-bound callable: keyword arguments by name.</summary>
        public static dynamic? __invoke_kw(object? f, object?[] args, IDictionary<string, object?>? kw)
        {
            if (kw == null || kw.Count == 0) return __invoke(f, args);
            if (f is PyFunction pf) return pf.__call_kw__(args, kw);
            if (f is PyBoundMethod bm) return bm.__call_kw__(args, kw);
            if (f is IPyKeywordCallable callable) return callable.__call_kw__(args, kw);
            // a typed function's value (a delegate of the method itself, or of a lambda): its parameters by name
            if (f is Delegate d)
            {
                if (PyArgs.Bind(d.Method.GetParameters(), args, kw, out var dcall) < 0) throw PyArgs.NoFit(d.Method.Name, kw, new[] { d.Method });
                try { return d.Method.Invoke(d.Target, dcall); }
                catch (System.Reflection.TargetInvocationException tie) when (tie.InnerException != null)
                {
                    System.Runtime.ExceptionServices.ExceptionDispatchInfo.Capture(tie.InnerException).Throw();
                    throw;
                }
            }
            if (f is Type t)
            {
                if (PyMetaclasses.TryBindMember(t, "__call__", out var metaclassCall))
                    return __invoke_kw(metaclassCall, args, kw);
                if (NativeClassFactory(t) is PyBoundMethod classFactory) return classFactory.__call_kw__(args, kw);
                if (PyMetaclasses.IsMetaclass(t) || t == typeof(Type) && args.Length != 1)
                    return PyMetaclasses.Create(t, args, kw);
                if (TryCustomAllocation(t, args, kw, out var allocated)) return allocated;
                if (TryAddedInitializer(t, args, kw, out allocated)) return allocated;
                Typhon.Stdlib._abc.CheckAbstract(t);
                if (t == typeof(MissingMemberException)) return __attribute_error(args, kw);
                if (t == typeof(PyPartial)) return ConstructPartial(args, kw);
                if (t == typeof(BigInteger)) return ConstructBigInt(args, kw);
                if (t == typeof(string)) return ConstructString(args, kw);
                if (t == typeof(PyBytes)) return ConstructBytes(args, kw);
                if (ByteSequenceFactory(t) is PyBoundMethod factory) return factory.__call_kw__(args, kw);
                if (TryConstructCollectionClass(t, args, kw, out var collection)) return collection;
                if (t == typeof(frozendict<object, object>)) return ConstructFrozenDict(args, kw);
                if (t == typeof(OrderedDictionary<object, object>)) return dict(ConstructFrozenDict(args, kw, "dict"));
                if (t == typeof(frozenset<object>)) throw new InvalidCastException("frozenset() takes no keyword arguments");
                var constructors = CallableConstructors(t);
                var ctor = PyArgs.Best(constructors, args, kw, out var call) ?? throw PyArgs.NoFit(t.Name, kw, constructors);
                try { return ctor.Invoke(call); }
                catch (System.Reflection.TargetInvocationException tie) when (tie.InnerException != null)
                {
                    System.Runtime.ExceptionServices.ExceptionDispatchInfo.Capture(tie.InnerException).Throw();
                    throw;
                }
            }
            if (f != null) return CallMember(f).__call_kw__(args, kw);
            throw new InvalidCastException("'NoneType' object is not callable");
        }

        public static T __construct_metaclass<T>(object?[] args, IDictionary<string, object?>? keywords)
            where T : class => (T)__invoke_kw(typeof(T), args, keywords);

        /// <summary>
        /// A decorated method's call: the decorators' result called with the instance (when there is one), the arguments
        /// given (an optional parameter left out, Type.Missing, is not passed; later ones then go by name), *args and **kwargs.
        /// </summary>
        public static dynamic? __forward(object? f, object?[] leading, object?[] values, string[] names, object?[]? rest, IDictionary? kwargs)
        {
            var positional = new List<object?>(leading);
            Dictionary<string, object?>? kw = null;
            bool skipped = false;
            for (int i = 0; i < values.Length; i++)
            {
                if (values[i] == System.Type.Missing) { skipped = true; continue; }
                if (!skipped) positional.Add(values[i]);
                else (kw ??= new Dictionary<string, object?>())[names[i]] = values[i];
            }
            if (rest != null) positional.AddRange(rest);
            if (kwargs != null) foreach (DictionaryEntry e in kwargs) (kw ??= new Dictionary<string, object?>())[(string)e.Key] = e.Value;
            return __invoke_kw(f, positional.ToArray(), kw);
        }

        /// <summary>The keyword arguments of a late-bound call: name=value pairs and **mappings, in order.</summary>
        public static Dictionary<string, object?> __kwdict(object?[] spreads, (string, object?)[] named)
        {
            var d = new Dictionary<string, object?>();
            foreach (var s in spreads)
            {
                if (s is IDictionary nd) { foreach (DictionaryEntry e in nd) d[(string)e.Key] = e.Value; }
                else if (s != null) throw new InvalidCastException($"argument after ** must be a mapping, not {s.GetType().Name}");
            }
            foreach (var (k, v) in named)
            {
                if (d.ContainsKey(k)) throw new ArgumentException($"got multiple values for keyword argument '{k}'");
                d[k] = v;
            }
            return d;
        }

        static PyBoundMethod? ByteSequenceFactory(Type type) => type == typeof(PyByteArray)
            ? new PyBoundMethod(typeof(Builtins), nameof(bytearray)) : null;

        internal static BigInteger ConstructBigInt(object?[] args, IDictionary<string, object?>? keywords)
        {
            if (keywords?.Count > 0)
            {
                if (keywords.Count != 1 || !keywords.TryGetValue("base", out var basis) || args.Length != 1)
                    throw new InvalidCastException("int() takes one positional value and an optional base");
                return __bigint(args[0]!, (long)__index_value(basis));
            }
            return args.Length switch
            {
                0 => BigInteger.Zero,
                1 when args[0] != null => __bigint(args[0]!),
                1 => throw new InvalidCastException("int() argument must be a string or a number, not 'NoneType'"),
                2 => __bigint(args[0]!, (long)__index_value(args[1])),
                _ => throw new InvalidCastException($"int() takes at most 2 arguments ({args.Length} given)"),
            };
        }

        static readonly object OmittedStringArgument = new();

        static string ConstructString(object?[] args, IDictionary<string, object?>? keywords)
        {
            if (keywords == null && args.Length <= 1) return args.Length == 0 ? str() : str(args[0]);

            var values = PyClosure.BindArguments("str", ["object", "encoding", "errors"],
                [OmittedStringArgument, OmittedStringArgument, OmittedStringArgument], 3, 0,
                args, keywords, varargs: false, kwargs: false, out _);
            string StringOption(object? option, string parameter, string defaultValue) => option switch
            {
                string text => text,
                PyString text => text.Text,
                PyStrEnum member => member.value,
                _ when ReferenceEquals(option, OmittedStringArgument) => defaultValue,
                _ => throw new InvalidCastException($"str() argument '{parameter}' must be str"),
            };
            string encoding = StringOption(values[1], "encoding", "utf-8");
            string errors = StringOption(values[2], "errors", "strict");
            if (ReferenceEquals(values[0], OmittedStringArgument)) return str();
            return ReferenceEquals(values[1], OmittedStringArgument) && ReferenceEquals(values[2], OmittedStringArgument)
                ? str(values[0]) : str(values[0], encoding, errors);
        }

        /// <summary>Builtin conversions, type(x), and object() through the type object of the builtin.</summary>
        static bool BuiltinTypeCall(Type t, object?[] args, out object? result)
        {
            result = null;
            if (t == typeof(PyBytes))
            {
                result = ConstructBytes(args, null);
                return true;
            }
            if (ByteSequenceFactory(t) is PyBoundMethod factory)
            {
                result = (object?)factory.__call__(args);
                return true;
            }
            if (t == typeof(BigInteger))
            {
                result = ConstructBigInt(args, null);
                return true;
            }
            if (t == typeof(long) && args.Length == 2 && args[0] is string integerText && args[1] is int or long)
            {
                result = @int(integerText, System.Convert.ToInt64(args[1]));
                return true;
            }
            if (t == typeof(string))
            {
                result = ConstructString(args, null);
                return true;
            }
            if (args.Length > 1) return false;
            object? a = args.Length == 1 ? args[0] : null;
            if (t == typeof(long)) result = args.Length == 0 ? 0L : @int(a!);
            else if (t == typeof(double)) result = args.Length == 0 ? 0.0 : @float(a!);
            else if (t == typeof(Complex))
                result = args.Length == 0 ? Complex.Zero : a switch
                {
                    string literal => complex(literal),
                    Complex number => number,
                    bool or byte or short or int or long or float or double or decimal or BigInteger => complex(@float(a)),
                    _ => throw new InvalidCastException("complex() first argument must be a string or a number"),
                };
            else if (t == typeof(bool)) result = args.Length == 1 && @bool(a);
            else if (t == typeof(Type) && args.Length == 1) result = __type_of(a);
            else if (t == typeof(ITuple)) result = new PyTuple<object?>(args.Length == 0 ? Array.Empty<object?>() : __iter_dyn(a));
            else if (t == typeof(List<object>)) result = args.Length == 0 ? new List<object?>() : __iter_dyn(a).ToList();
            else if (t == typeof(HashSet<object>))
            {
                var set = __newset<object?>();
                if (args.Length != 0) set.UnionWith(__iter_dyn(a));
                result = set;
            }
            else if (t == typeof(OrderedDictionary<object, object>))
                result = args.Length == 0 ? __newdict<object, object?>() : dict(a);
            else if (t == typeof(object) && args.Length == 0) result = new object();
            else return false;
            return true;
        }

        public static bool __has_packed_method(object? receiver, string name) =>
            receiver != null && receiver.GetType().IsDefined(typeof(PySourceAttribute), false) &&
            receiver.GetType().GetMethods(InstanceMembers).Any(method => method.Name == name &&
                method.GetParameters().Any(parameter => parameter.IsDefined(typeof(PyPackedArgumentsAttribute), false)));

        public static dynamic? __invoke(object? f, object?[] args) => f switch
        {
            PyFunction pf => pf.__call__(args),
            PyBoundMethod bm => bm.__call__(args),
            IPyKeywordCallable callable => callable.__call_kw__(args, null),
            Delegate d => Unwrapped(() => d.DynamicInvoke(args)),
            // a builtin type as a value (conv = int; conv("5")): the builtin's conversion
            Type t when PyMetaclasses.TryBindMember(t, "__call__", out var metaclassCall) => __invoke(metaclassCall, args),
            Type t when PyMetaclasses.IsMetaclass(t) || t == typeof(Type) && args.Length != 1 =>
                PyMetaclasses.Create(t, args, null),
            Type t when t == typeof(MissingMemberException) => __attribute_error(args),
            Type t when t == typeof(PyPartial) => ConstructPartial(args, null),
            Type t when BuiltinTypeCall(t, args, out var converted) => converted,
            // a class passed as a value (cls = Array2D; cls(n, n)): constructed with the constructor that fits the arguments
            Type t => Construct(t, args),
            null => throw new NullReferenceException("'NoneType' object is not callable"),
            _ => CallMember(f).__call__(args),
        };

        static PyPartial ConstructPartial(object?[] args, IDictionary<string, object?>? keywords) => args.Length > 0
            ? new PyPartial(args[0], args[1..], keywords)
            : throw new InvalidCastException("type 'partial' takes at least one argument");

        static PyBoundMethod CallMember(object callable) => new PyBoundMethod(callable, "__call__",
            includeNonPublic: callable.GetType().IsDefined(typeof(PySourceAttribute), false));
    }

    /// <summary>A Python class that uses its explicit __new__ for construction.</summary>
    [AttributeUsage(AttributeTargets.Class, Inherited = false)]
    internal sealed class PyCustomAllocationAttribute : Attribute { }

    /// <summary>A CLR virtual slot used to forward to a different Python signature.</summary>
    [AttributeUsage(AttributeTargets.Method)]
    internal sealed class PyOverrideBridgeAttribute : Attribute { }

    [AttributeUsage(AttributeTargets.Method)]
    internal sealed class PyHidesBaseMethodAttribute : Attribute { }

    /// <summary>A CLR virtual slot synthesized solely for methods introduced in Python subclasses.</summary>
    [AttributeUsage(AttributeTargets.Method, Inherited = false)]
    internal sealed class PyMissingMethodAttribute : Attribute { }

    /// <summary>Marks *args when a following parameter prevents the array from being declared as C# params.</summary>
    [AttributeUsage(AttributeTargets.Parameter)]
    internal sealed class PyPackedArgumentsAttribute : Attribute { }

    [AttributeUsage(AttributeTargets.Parameter)]
    internal sealed class PyKeywordArgumentsAttribute : Attribute { }

    [AttributeUsage(AttributeTargets.Parameter)]
    internal sealed class PyPositionalOnlyAttribute : Attribute { }

    [AttributeUsage(AttributeTargets.Parameter)]
    internal sealed class PyKeywordOnlyAttribute : Attribute { }

    internal interface IPyKeywordCallable
    {
        object? __call_kw__(object?[] args, IDictionary<string, object?>? kwargs);
    }

    /// <summary>
    /// Selects a Typhon class's allocation-only constructor: in a hierarchy where a subclass runs its base class's
    /// __init__ later in its own (after setting attributes the base's __init__ reads), construction is two-phase like
    /// Python's: the constructor allocates, __init__ is a method each class calls on its base where Python does.
    /// </summary>
    internal readonly struct NoInit { }

    /// <summary>
    /// A Typhon function used as a value. Each such function gets its own sealed subclass with one instance, so the compiler
    /// knows statically which function a variable or parameter holds (a call through it becomes a direct call, and a
    /// parameter receiving it is specialised per function, like a C++ template argument). Where the static type is lost
    /// (a list of functions, a dynamic variable) it is still callable: the call is dispatched by the arguments' run-time types.
    /// </summary>
    internal abstract class PyFunction : System.Dynamic.DynamicObject
    {
        public string __name__;
        public object? __doc__;
        /// <summary>The function a decorator's wrapper wraps (set by functools.wraps).</summary>
        public object? __wrapped__;
        public string __module__ = "__main__";
        public string __qualname__;
        internal Func<Typhon.Stdlib.inspect.Signature>? _signature;
        internal Typhon.Stdlib.types.CodeType? _code;
        public Typhon.Stdlib.types.CodeType? __code__ =>
            _code ?? (GetType().GetCustomAttributes(typeof(PySourceAttribute), false).FirstOrDefault() is PySourceAttribute { Line: > 0 } source
                ? new Typhon.Stdlib.types.CodeType(__name__, source.Filename, source.Line) : null);
        public virtual IDictionary? __globals__ => GetType().DeclaringType is Type owner ? PyModule.Of(owner, __module__).__dict__ : null;
        public IDictionary __builtins__ => PyModule.Of(typeof(Typhon.Stdlib.builtins), "builtins").__dict__;
        public virtual ITuple? __defaults__
        {
            get
            {
                var defaults = _signature?.Invoke().Arguments
                    .Where(p => p.kind is Typhon.Stdlib.inspect._ParameterKind.POSITIONAL_ONLY or Typhon.Stdlib.inspect._ParameterKind.POSITIONAL_OR_KEYWORD)
                    .Select(p => (object?)p.@default).Where(value => !ReferenceEquals(value, Typhon.Stdlib.inspect.Signature.empty)).ToArray();
                return defaults is { Length: > 0 } ? new PyTuple<object?>(defaults) : null;
            }
        }
        public virtual IDictionary? __kwdefaults__
        {
            get
            {
                var defaults = _signature?.Invoke().Arguments.Where(p => p.kind == Typhon.Stdlib.inspect._ParameterKind.KEYWORD_ONLY &&
                    !ReferenceEquals((object?)p.@default, Typhon.Stdlib.inspect.Signature.empty)).ToDictionary(p => p.name, p => (object?)p.@default);
                return defaults is { Count: > 0 } ? defaults : null;
            }
        }
        public virtual ITuple? __closure__ => null;
        public IDictionary<string, object?> __annotations__
        {
            get => _annotations ??= ReadAnnotations();
            set => _annotations = value;
        }
        IDictionary<string, object?>? _annotations;
        IDictionary<string, object?> ReadAnnotations()
        {
            var result = new OrderedDictionary<string, object?>();
            if (_signature?.Invoke() is Typhon.Stdlib.inspect.Signature signature)
            {
                foreach (var parameter in signature.Arguments)
                    if (!ReferenceEquals((object?)parameter.annotation, Typhon.Stdlib.inspect.Signature.empty))
                        result[parameter.name] = parameter.annotation;
                if (!ReferenceEquals((object?)signature.return_annotation, Typhon.Stdlib.inspect.Signature.empty))
                    result["return"] = signature.return_annotation;
            }
            return result;
        }
        internal IDictionary? _attrs;

        internal bool TryStoredAttribute(string name, out object? value)
        {
            if (_attrs is { } dictionary && dictionary.Contains(name))
            {
                value = dictionary[name];
                return true;
            }
            value = null;
            return false;
        }

        internal bool RemoveStoredAttribute(string name)
        {
            if (_attrs is not { } dictionary || !dictionary.Contains(name)) return false;
            dictionary.Remove(name);
            return true;
        }
        protected PyFunction(string name) { __name__ = __qualname__ = name; }

        public virtual object __get__(object? instance, object? owner = null)
        {
            if (instance != null) return new Typhon.Stdlib.types.MethodType(this, instance);
            if (owner == null) throw new InvalidCastException("__get__(None, None) is invalid");
            return this;
        }

        /// <summary>Calls the function with arguments of any type (dynamic overload resolution).</summary>
        public abstract object? __call__(object?[] args);
        /// <summary>The parameter names, for keyword arguments (null: the function takes none by name).</summary>
        protected virtual string[]? __params__ => null;
        /// <summary>The parameter names (for the test runner's fixtures), or null when unknown.</summary>
        public string[]? __param_names__ => __params__;
        /// <summary>A call with keyword arguments: f(*args, **kwargs) on a function value.</summary>
        public virtual object? __call_kw__(object?[] args, IDictionary<string, object?>? kw)
        {
            if (kw == null || kw.Count == 0) return __call__(args);
            var names = __params__ ?? throw new ArgumentException($"{__name__}() got an unexpected keyword argument '{kw.Keys.First()}'");
            return __call__(PyClosure.Args(__name__, names, args, kw, false));
        }
        public override bool TryInvoke(System.Dynamic.InvokeBinder binder, object?[]? args, out object? result)
        {
            args ??= Array.Empty<object?>();
            var names = binder.CallInfo.ArgumentNames;
            if (names.Count == 0) { result = __call__(args); return true; }
            // f(x, key=1) through a late-bound value: the named arguments come last
            int positional = args.Length - names.Count;
            var kw = new Dictionary<string, object?>();
            for (int i = 0; i < names.Count; i++) kw[names[i]] = args[positional + i];
            result = __call_kw__(args.Take(positional).ToArray(), kw);
            return true;
        }
        // attributes set on a function (wrapper.calls = 0), as Python allows
        public override bool TryGetMember(System.Dynamic.GetMemberBinder binder, out object? result)
        {
            if (TryStoredAttribute(binder.Name, out result)) return true;
            throw new MissingMemberException($"'function' object has no attribute '{binder.Name}'");
        }
        public override bool TrySetMember(System.Dynamic.SetMemberBinder binder, object? value) { (_attrs ??= new Dictionary<string, object?>())[binder.Name] = value; return true; }
        protected static Exception ArgCount(string name, int min, int max, int given) => new ArgumentException(
            $"{name}() takes {(min == max ? min.ToString() : $"from {min} to {max}")} positional argument{(max == 1 ? "" : "s")} but {given} {(given == 1 ? "was" : "were")} given");
        public override string ToString() => $"<function {__name__} at 0x{RuntimeHelpers.GetHashCode(this):x12}>";
    }

    /// <summary>
    /// A function made at run time as a value: a nested function (a decorator's wrapper, a returned closure), a
    /// functools.partial, a decorator's result. It is called with positional arguments and keyword arguments by name.
    /// </summary>
    internal class PyClosure : PyFunction
    {
        readonly Func<object?[], IDictionary<string, object?>?, object?> _call;
        public PyClosure(string name, Func<object?[], IDictionary<string, object?>?, object?> call) : base(name) { _call = call; }
        public PyClosure(string name, object?[] defaults, Func<object?[], IDictionary<string, object?>?, object?[], object?> call)
            : this(name, (args, kw) => call(args, kw, defaults)) { }
        public override object? __call__(object?[] args) => _call(args, null);
        public override object? __call_kw__(object?[] args, IDictionary<string, object?>? kw) => _call(args, kw);

        internal static PyClosure? FromCallable(object? callable) => callable switch
        {
            null => null,
            PyClosure closure => closure,
            _ => new PyClosure("callback", (args, keywords) => Builtins.__invoke_kw(callable, args, keywords)),
        };

        /// <summary>
        /// The positional arguments with the keyword arguments for named parameters put in their places. A keyword that
        /// names no parameter is an error unless the function takes **kwargs (<paramref name="extraKeywords"/>).
        /// </summary>
        public static object?[] Args(string fn, string[] names, object?[] args, IDictionary<string, object?>? kw, bool extraKeywords) =>
            Args(fn, names, args, kw, extraKeywords, null);

        public static object?[] Args(string fn, string[] names, object?[] args, IDictionary<string, object?>? kw, bool extraKeywords,
            object?[]? defaults)
        {
            if ((kw == null || kw.Count == 0) && (defaults == null || args.Length >= names.Length)) return args;
            Exception Error(string message) => defaults == null ? new ArgumentException(message) : new InvalidCastException(message);
            int n = defaults == null ? args.Length : Math.Max(args.Length, names.Length);
            if (kw != null)
                foreach (var k in kw.Keys)
                {
                    int i = Array.IndexOf(names, k);
                    if (i < 0)
                    {
                        if (extraKeywords) continue;
                        throw Error($"{fn}() got an unexpected keyword argument '{k}'");
                    }
                    if (i < args.Length) throw Error($"{fn}() got multiple values for argument '{k}'");
                    n = Math.Max(n, i + 1);
                }
            var a = new object?[n];
            Array.Copy(args, a, args.Length);
            int required = names.Length - (defaults?.Length ?? 0);
            for (int i = args.Length; i < n; i++)
            {
                if (kw != null && kw.TryGetValue(names[i], out a[i])) continue;
                if (defaults == null || i < required)
                    throw Error($"{fn}() missing required argument: '{names[i]}'");
                a[i] = defaults[i - required];
            }
            return a;
        }

        public static readonly object RequiredArgument = new();

        public static object?[] BindArguments(string fn, string[] names, object?[] defaults, int positional, int positionalOnly,
            object?[] args, IDictionary<string, object?>? kw, bool varargs, bool kwargs,
            out IDictionary<string, object?>? extraKeywords)
        {
            int count = Math.Min(args.Length, positional);
            int extraCount = args.Length - count;
            if (!varargs && extraCount > 0)
                throw new InvalidCastException(ArgCountError(fn, defaults.Take(positional)
                    .Count(value => value == RequiredArgument), positional, args.Length).Message);
            var bound = new object?[names.Length + extraCount];
            defaults.CopyTo(bound, 0);
            Array.Copy(args, bound, count);
            Array.Copy(args, count, bound, names.Length, extraCount);
            extraKeywords = null;
            if (kw != null)
            {
                foreach (var item in kw)
                {
                    int index = Array.IndexOf(names, item.Key, positionalOnly);
                    if (index < 0)
                    {
                        if (!kwargs) throw new InvalidCastException($"{fn}() got an unexpected keyword argument '{item.Key}'");
                        (extraKeywords ??= new Dictionary<string, object?>()).Add(item.Key, item.Value);
                    }
                    else
                    {
                        if (index < count)
                            throw new InvalidCastException($"{fn}() got multiple values for argument '{item.Key}'");
                        bound[index] = item.Value;
                    }
                }
            }
            for (int index = 0; index < names.Length; index++)
                if (bound[index] == RequiredArgument)
                    throw new InvalidCastException($"{fn}() missing required argument: '{names[index]}'");
            return bound;
        }

        /// <summary>The keyword arguments that name no parameter: a function's **kwargs dict.</summary>
        public static OrderedDictionary<string, object> Kw(IDictionary<string, object?>? kw, string[] names)
        {
            var d = new OrderedDictionary<string, object>();
            if (kw != null) foreach (var kv in kw) if (Array.IndexOf(names, kv.Key) < 0) d[kv.Key] = kv.Value!;
            return d;
        }

        public static Exception ArgCountError(string name, int min, int max, int given) => ArgCount(name, min, max, given);
    }

    /// <summary>functools.partial(func, *args, **keywords): func with some arguments given in advance.</summary>
    internal sealed class PyPartial : PyFunction, IPyRepr
    {
        sealed record Invocation(object Function, ITuple Arguments, IDictionary Keywords);
        Invocation _invocation;

        public object func => _invocation.Function;
        public ITuple args => _invocation.Arguments;
        public IDictionary keywords => _invocation.Keywords;
        public IDictionary __dict__ => _attrs ??= Builtins.__newdict<object, object?>();

        public PyPartial(object? func, object?[] args, IDictionary<string, object?>? keywords)
            : base((func as PyFunction)?.__name__ ?? "partial")
        {
            if (!Builtins.callable(func)) throw new InvalidCastException("the first argument must be callable");
            var copied = new OrderedDictionary<string, object?>();
            if (keywords != null)
                foreach (var pair in keywords) copied[pair.Key] = pair.Value;
            _invocation = new Invocation(func!, new PyTuple<object?>(args), copied);
            __module__ = "functools";
        }

        public override object? __call__(object?[] args) => __call_kw__(args, null);

        public override object? __call_kw__(object?[] args, IDictionary<string, object?>? keywords)
        {
            Invocation current = _invocation;
            var all = new Dictionary<string, object?>();
            foreach (DictionaryEntry pair in current.Keywords)
            {
                if (pair.Key is not string name) throw new InvalidCastException("keywords must be strings");
                all[name] = pair.Value;
            }
            if (keywords != null)
                foreach (var pair in keywords) all[pair.Key] = pair.Value;
            return Builtins.__invoke_kw(current.Function, [.. Builtins.__iter_dyn(current.Arguments), .. args], all);
        }

        public object __reduce__()
        {
            Invocation current = _invocation;
            return (typeof(PyPartial), new PyTuple<object?>([current.Function]),
                new PyTuple<object?>([current.Function, current.Arguments, current.Keywords, _attrs]));
        }

        public object? __setstate__([PyPositionalOnly] object? state)
        {
            if (state is not ITuple { Length: 4 } values || !Builtins.callable(values[0]) ||
                values[1] is not ITuple positional ||
                values[2] != null && !IsDictionary(values[2]) ||
                values[3] != null && !IsDictionary(values[3]))
                throw new InvalidCastException("invalid partial state");
            IDictionary restoredKeywords = values[2] switch
            {
                null => Builtins.__newdict<object, object?>(),
                IDictionary mapping when Builtins.__type_of(mapping) == typeof(OrderedDictionary<object, object>) => mapping,
                _ => Builtins.dict(values[2]),
            };
            ITuple restoredArgs = Builtins.__type_of(positional) == typeof(ITuple) ? positional :
                new PyTuple<object?>(Builtins.__iter_dyn(positional));
            _invocation = new Invocation(values[0]!, restoredArgs, restoredKeywords);
            _attrs = (IDictionary?)values[3];
            return null;
        }

        static bool IsDictionary(object? value) => value is IDictionary &&
            Builtins.IsSubclass(Builtins.__type_of(value), typeof(OrderedDictionary<object, object>));

        internal void SetAttribute(string name, object? value)
        {
            if (name is "func" or "args" or "keywords") throw new MissingMemberException("readonly attribute");
            if (name == "__dict__")
            {
                if (!IsDictionary(value)) throw new InvalidCastException("__dict__ must be set to a dictionary");
                _attrs = (IDictionary)value!;
            }
            else __dict__[name] = value;
        }

        public override bool TrySetMember(System.Dynamic.SetMemberBinder binder, object? value)
        {
            SetAttribute(binder.Name, value);
            return true;
        }

        public string __repr__()
        {
            Invocation current = _invocation;
            var positional = Builtins.__iter_dyn(current.Arguments).Select(value => Builtins.repr((object?)value));
            var named = Builtins.ReadDictItems(current.Keywords).Select(pair => $"{pair.Key}={Builtins.repr(pair.Value)}");
            return "functools.partial(" + string.Join(", ", new[] { Builtins.repr(current.Function) }.Concat(positional).Concat(named)) + ")";
        }
        public override string ToString() => __repr__();
    }

    internal static partial class Builtins
    {
        static readonly CultureInfo Inv = CultureInfo.InvariantCulture;
    }
}
